<script setup>
import { computed, nextTick, ref, watch } from 'vue'
import { ChevronDown, ChevronRight, FileText, FolderOpen, Layers3, X } from 'lucide-vue-next'

const props = defineProps({ skill: { type: Object, required: true }, examName: { type: String, required: true }, sets: { type: Array, default: () => [] }, loading: { type: Boolean, default: false }, error: { type: String, default: '' } })
const emit = defineEmits(['close', 'question'])
const expandedSets = ref(new Set()), expandedSections = ref(new Set()), expandedGroups = ref(new Set()), activeId = ref(null)

function parse(value, fallback = {}) { if (!value) return fallback; try { return typeof value === 'string' ? JSON.parse(value) : value } catch { return fallback } }
function questionContent(question) { const parsed = parse(question.contentJson, {}); return question.content || question.questionText || question.stem || question.prompt || parsed.content || 'Chưa có nội dung câu hỏi' }
function options(question) { const value = Array.isArray(question.options) ? question.options : parse(question.optionsJson, []); return Array.isArray(value) ? value.map((item, index) => ({ key: item?.key || String.fromCharCode(65 + index), value: item?.value || item?.text || item?.label || item })) : Object.entries(value || {}).map(([key, value]) => ({ key, value })) }
function mediaItems(question) { const value = parse(question.contentJson, {}); return (Array.isArray(value) ? value : Object.values(value)).filter((item) => typeof item === 'string' && /\.(png|jpe?g|gif|mp3|wav|ogg|mp4|webm)(\?.*)?$/i.test(item)) }
function questionType(value) { return ({ MULTIPLE_CHOICE: 'Trắc nghiệm', FILL_BLANK: 'Điền vào chỗ trống', TRUE_FALSE: 'Đúng / Sai', MATCHING: 'Nối đáp án', SHORT_ANSWER: 'Trả lời ngắn', ESSAY: 'Tự luận' }[value] || value || 'Câu hỏi') }
function buildGroups(questions, prefix) {
  const groups = [], map = new Map()
  questions.forEach((question, index) => { const parsed = parse(question.contentJson, {}); const stimulus = question.groupStimulusContent || question.stimulusContent || parsed.groupStimulusContent || parsed.stimulusContent || ''; const key = question.sourceGroupOrder != null ? `${prefix}-${question.sourceGroupOrder}` : `${prefix}-${stimulus || 'independent'}`; if (!map.has(key)) { const group = { key, title: question.sourceGroupTitle || parsed.sourceGroupTitle || (stimulus ? 'Nội dung nguồn' : 'Câu hỏi độc lập'), instruction: question.groupInstruction || parsed.groupInstruction || '', stimulus, questions: [] }; map.set(key, group); groups.push(group) } map.get(key).questions.push({ ...question, questionId: question.questionId ?? `${prefix}-question-${index}`, questionOrder: question.questionOrder ?? index + 1 }) })
  return groups
}
const structure = computed(() => props.sets.map((set) => ({ ...set, sections: (set.sections || []).map((section) => ({ ...section, groups: buildGroups(section.questions || [], `${section.key}-group`) })) })))
const allQuestions = computed(() => structure.value.flatMap((set) => set.sections.flatMap((section) => section.questions || [])))
const totalSections = computed(() => structure.value.reduce((total, set) => total + set.sections.length, 0))
const totalPoints = computed(() => allQuestions.value.reduce((total, question) => total + Number(question.pointsOverride ?? question.points ?? 0), 0))
function expandAll() { expandedSets.value = new Set(structure.value.map((item) => item.key)); expandedSections.value = new Set(structure.value.flatMap((item) => item.sections.map((section) => section.key))); expandedGroups.value = new Set(structure.value.flatMap((item) => item.sections.flatMap((section) => section.groups.map((group) => group.key)))) }
function toggle(target, key) { const next = new Set(target.value); next.has(key) ? next.delete(key) : next.add(key); target.value = next }
function goTo(question) { activeId.value = question.questionId; nextTick(() => document.getElementById(`skill-preview-question-${question.questionId}`)?.scrollIntoView({ behavior: 'smooth', block: 'center' })) }
watch(structure, expandAll, { immediate: true })
</script>

<template>
  <div class="preview-backdrop" role="dialog" aria-modal="true" aria-label="Xem trước kỹ năng"><section class="preview-shell">
    <header class="preview-header"><div><span class="eyebrow">XEM TRƯỚC KỸ NĂNG</span><h2>{{ skill.name }}</h2><p>{{ examName }}</p></div><button class="icon-button" type="button" title="Đóng xem trước" aria-label="Đóng xem trước" @click="emit('close')"><X :size="20" /></button></header>
    <div class="preview-summary"><span><b>{{ sets.length }}</b> bộ đề</span><span><b>{{ totalSections }}</b> section</span><span><b>{{ allQuestions.length }}</b> câu hỏi</span><span><b>{{ totalPoints }}</b> điểm</span></div>
    <div v-if="loading" class="preview-state">Đang tải cấu trúc kỹ năng...</div><div v-else-if="error" class="preview-state error" role="alert">{{ error }}</div><div v-else-if="!structure.length" class="preview-state"><Layers3 :size="30" /><strong>Chưa có bộ đề phù hợp</strong><span>Không có câu hỏi của kỹ năng này trong các bộ đề đang hoạt động.</span></div>
    <div v-else class="preview-layout"><aside class="navigator" aria-label="Điều hướng nội dung kỹ năng"><div class="navigator-heading"><strong>{{ skill.name }}</strong><span>{{ allQuestions.length }}</span></div>
      <div v-for="set in structure" :key="set.key"><button class="nav-row set-row" type="button" @click="toggle(expandedSets, set.key)"><component :is="expandedSets.has(set.key) ? ChevronDown : ChevronRight" :size="16" /><FolderOpen :size="16" /><strong>{{ set.title }}</strong><small>{{ set.sections.reduce((sum, section) => sum + section.questions.length, 0) }}</small></button><div v-if="expandedSets.has(set.key)" class="nav-children">
        <div v-for="section in set.sections" :key="section.key"><button class="nav-row section-row" type="button" @click="toggle(expandedSections, section.key)"><component :is="expandedSections.has(section.key) ? ChevronDown : ChevronRight" :size="15" /><Layers3 :size="15" /><strong>{{ section.title }}</strong><small>{{ section.questions.length }}</small></button><div v-if="expandedSections.has(section.key)" class="nav-groups">
          <div v-for="group in section.groups" :key="group.key"><button class="nav-row group-row" type="button" @click="toggle(expandedGroups, group.key)"><component :is="expandedGroups.has(group.key) ? ChevronDown : ChevronRight" :size="14" /><span>{{ group.title }}</span><small>{{ group.questions.length }}</small></button><div v-if="expandedGroups.has(group.key)" class="nav-questions"><button v-for="question in group.questions" :key="question.questionId" type="button" class="nav-question" :class="{ active: activeId === question.questionId }" @click="goTo(question)"><FileText :size="14" /><span>Câu {{ question.questionOrder }}</span><small>{{ questionType(question.questionType) }}</small></button></div></div>
        </div></div>
      </div></div>
    </aside><main class="preview-main"><div class="content-heading"><div><span class="eyebrow">NỘI DUNG CHI TIẾT</span><h3>{{ skill.name }}</h3></div><span class="readonly-badge">Chỉ đọc</span></div>
      <article v-for="set in structure" :key="set.key" class="exam-set"><header class="set-heading"><span>BỘ ĐỀ</span><h3>{{ set.title }}</h3><p>{{ set.sections.length }} section · {{ set.sections.reduce((sum, section) => sum + section.questions.length, 0) }} câu hỏi</p></header><section v-for="section in set.sections" :key="section.key" class="exam-section"><header class="section-heading"><span>SECTION</span><h4>{{ section.title }}</h4><p>{{ section.questions.length }} câu hỏi</p></header>
        <div v-for="group in section.groups" :key="group.key" class="question-group"><div class="group-heading"><strong>{{ group.title }}</strong><span>{{ group.questions.length }} câu</span></div><p v-if="group.instruction" class="instruction">{{ group.instruction }}</p><div v-if="group.stimulus" class="stimulus">{{ group.stimulus }}</div><article v-for="question in group.questions" :id="`skill-preview-question-${question.questionId}`" :key="question.questionId" class="question-card" :class="{ active: activeId === question.questionId }" @click="activeId = question.questionId"><div class="question-title"><span class="question-number">{{ question.questionOrder }}</span><div><span class="question-type">{{ questionType(question.questionType) }}</span><p>{{ questionContent(question) }}</p></div></div><div v-if="mediaItems(question).length" class="media-list"><template v-for="source in mediaItems(question)" :key="source"><img v-if="/\.(png|jpe?g|gif)/i.test(source)" :src="source" alt="Nội dung hình ảnh" /><audio v-else-if="/\.(mp3|wav|ogg)/i.test(source)" :src="source" controls /><video v-else :src="source" controls /></template></div><div v-if="options(question).length" class="options"><div v-for="option in options(question)" :key="option.key" class="option"><b>{{ option.key }}</b><span>{{ option.value }}</span></div></div><footer class="question-meta"><span>Đáp án: {{ question.correctAnswer || 'Chưa có đáp án' }}</span><span>Điểm: {{ question.pointsOverride ?? question.points ?? 0 }}</span></footer></article></div>
      </section></article>
    </main></div>
  </section></div>
</template>

<style scoped>
.preview-backdrop{position:fixed;z-index:100;inset:0;display:flex;background:#0f172acc}.preview-shell{display:flex;width:100%;height:100%;flex-direction:column;background:#f8fafc}.preview-header{display:flex;align-items:flex-start;justify-content:space-between;gap:20px;padding:20px 28px;border-bottom:1px solid #e2e8f0;background:#fff}.eyebrow{color:#2563eb;font-size:11px;font-weight:700;letter-spacing:.08em}.preview-header h2{margin:6px 0;color:#0f172a;font-size:22px}.preview-header p{margin:0;color:#64748b;font-size:13px}.icon-button{display:grid;width:36px;height:36px;place-items:center;border:1px solid #cbd5e1;border-radius:8px;background:#fff;color:#334155;cursor:pointer}.preview-summary{display:flex;gap:24px;flex-wrap:wrap;padding:11px 28px;border-bottom:1px solid #e2e8f0;color:#64748b;background:#fff;font-size:12px}.preview-summary b{margin-right:3px;color:#0f172a;font-size:14px}.preview-layout{display:grid;min-height:0;flex:1;grid-template-columns:280px minmax(0,1fr)}.navigator{overflow:auto;padding:16px 12px;border-right:1px solid #e2e8f0;background:#fff;overscroll-behavior:contain}.navigator-heading{display:flex;justify-content:space-between;margin:0 6px 12px;color:#334155;font-size:13px}.navigator-heading span,.nav-row small{color:#64748b;font-size:11px}.nav-row{display:flex;width:100%;min-width:0;align-items:center;gap:7px;border:0;background:transparent;color:#334155;font:inherit;text-align:left;cursor:pointer}.nav-row strong,.nav-row span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.nav-row small{margin-left:auto;flex:0 0 auto}.set-row{min-height:40px;padding:7px 6px;color:#0f172a}.set-row svg:nth-child(2){color:#2563eb}.nav-children{margin-left:11px;border-left:1px solid #dbe4f0}.section-row{min-height:36px;padding:6px 7px}.section-row svg:nth-child(2){color:#059669}.nav-groups{margin-left:13px;border-left:1px solid #edf2f7}.group-row{min-height:32px;padding:5px 7px;color:#475569;font-size:12px}.nav-questions{margin-left:17px;border-left:1px solid #edf2f7}.nav-question{display:flex;width:100%;align-items:center;gap:7px;min-height:31px;padding:5px 7px;border:0;color:#64748b;background:transparent;font:inherit;font-size:12px;text-align:left;cursor:pointer}.nav-question small{overflow:hidden;margin-left:auto;color:#94a3b8;font-size:9px;text-overflow:ellipsis;white-space:nowrap}.nav-question:hover,.nav-question.active{color:#1d4ed8;background:#dbeafe}.nav-question.active{font-weight:700}.preview-main{min-width:0;overflow:auto;padding:22px 32px 64px;scroll-behavior:smooth}.content-heading{display:flex;align-items:flex-start;justify-content:space-between;max-width:920px;margin:0 auto 18px}.content-heading h3{margin:5px 0 0;color:#0f172a;font-size:18px}.readonly-badge{padding:5px 9px;border:1px solid #bbf7d0;border-radius:999px;color:#047857;background:#f0fdf4;font-size:11px;font-weight:700}.exam-set{max-width:920px;margin:0 auto 24px}.set-heading{padding:16px 18px;border:1px solid #bfdbfe;border-radius:8px 8px 0 0;background:#eff6ff}.set-heading span,.section-heading span{color:#2563eb;font-size:10px;font-weight:700;letter-spacing:.08em}.set-heading h3{margin:5px 0 3px;color:#0f172a;font-size:18px}.set-heading p,.section-heading p{margin:0;color:#64748b;font-size:12px}.exam-section{padding:18px;border:1px solid #e2e8f0;border-top:0;background:#fff}.section-heading{display:flex;align-items:baseline;gap:10px;flex-wrap:wrap;margin-bottom:15px}.section-heading h4{margin:0;color:#0f172a;font-size:16px}.question-group+.question-group{margin-top:18px;padding-top:18px;border-top:1px solid #edf2f7}.group-heading{display:flex;justify-content:space-between;gap:10px;color:#334155;font-size:13px}.group-heading span{color:#64748b;font-size:11px}.instruction,.stimulus{margin:8px 0;color:#475569;font-size:13px;line-height:1.6;white-space:pre-wrap}.stimulus{padding:12px;border-left:3px solid #93c5fd;background:#f8fafc}.question-card{margin-top:10px;padding:15px;border:1px solid #e2e8f0;border-radius:7px;scroll-margin-top:18px;cursor:pointer}.question-card:hover,.question-card.active{border-color:#60a5fa;box-shadow:0 0 0 3px #dbeafe}.question-title{display:flex;gap:11px}.question-number{display:grid;width:28px;height:28px;flex:0 0 auto;place-items:center;border-radius:50%;color:#1d4ed8;background:#eff6ff;font-size:12px;font-weight:700}.question-type{color:#64748b;font-size:10px}.question-title p{margin:5px 0 0;color:#0f172a;font-size:14px;line-height:1.55;white-space:pre-wrap}.media-list,.options{display:grid;gap:8px;margin:13px 0 0 39px}.media-list img,.media-list video{max-width:100%;max-height:280px;object-fit:contain}.media-list audio{width:100%}.option{display:flex;gap:9px;padding:9px 11px;border:1px solid #e2e8f0;border-radius:6px;color:#475569;font-size:13px}.option b{color:#2563eb}.question-meta{display:flex;gap:14px;flex-wrap:wrap;margin:13px 0 0 39px;padding-top:10px;border-top:1px solid #e2e8f0;color:#64748b;font-size:11px}.preview-state{display:grid;min-height:250px;flex:1;place-content:center;justify-items:center;gap:8px;padding:24px;color:#64748b;text-align:center}.preview-state strong{color:#334155}.preview-state.error{color:#b91c1c}@media(max-width:760px){.preview-header,.preview-summary{padding-right:16px;padding-left:16px}.preview-layout{grid-template-columns:1fr}.navigator{max-height:34vh;border-right:0;border-bottom:1px solid #e2e8f0}.preview-main{padding:18px 14px 44px}.exam-section{padding:14px}.question-meta,.options,.media-list{margin-left:0}}
/* The detail pane owns the full width left after the navigator. */
.preview-main .content-heading,.preview-main .exam-set{width:100%;max-width:none;margin-left:0;margin-right:0}
</style>
